-- Dhamma Capital CRM — Cloudflare D1 schema + seed.
-- Idempotent: safe to re-apply. Applying this makes the CRM alive with ~120 sample contacts.
-- Apply with:  wrangler d1 execute dccrm --file=./schema.sql --remote

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS contacts (
  id                INTEGER PRIMARY KEY AUTOINCREMENT,
  fullName          TEXT,
  entityType        TEXT,
  role              TEXT,
  organisation      TEXT,
  designation       TEXT,
  email             TEXT UNIQUE,
  phone             TEXT,
  whatsapp          TEXT,
  whatsappOptIn     TEXT,
  country           TEXT,
  city              TEXT,
  vehicle           TEXT,
  stage             TEXT,
  referredBy        TEXT,
  lastContact       TEXT,
  nextAction        TEXT,
  nextActionDate    TEXT,
  relationshipOwner TEXT,
  source            TEXT,
  notes             TEXT,
  createdAt         TEXT NOT NULL,
  updatedAt         TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS activities (
  id         INTEGER PRIMARY KEY AUTOINCREMENT,
  contactId  INTEGER NOT NULL,
  type       TEXT,
  summary    TEXT,
  occurredAt TEXT,
  createdAt  TEXT NOT NULL,
  FOREIGN KEY (contactId) REFERENCES contacts(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_activities_contactId ON activities(contactId);
CREATE INDEX IF NOT EXISTS idx_contacts_stage ON contacts(stage);
CREATE INDEX IF NOT EXISTS idx_contacts_owner ON contacts(relationshipOwner);

-- Seed: existing sample contacts. INSERT OR IGNORE keeps re-applies idempotent (email is UNIQUE).
